import{m as r,o as t,R as c}from"./index-CyQ9o3df.js";const s="tcle_v1_2025-11-28",l={title:"Avaliação do SRL Canvas - Diagnóstico de Maturidade de Startups",researcher:"Marcelo Siqueira Alexandre da Silva - Mestrando no PROFNIT (ponto focal IFMS)",researcherContact:"marcelo.silva20@estudante.ifms.edu.br | (67) 98107-0505",advisor:"Prof. Dr. Jiyan Yari - Orientador (IFMS) | jiyan.yari@ifms.edu.br",institution:"Instituto Federal de Mato Grosso do Sul (IFMS)",program:"PROFNIT - Programa de Pós-Graduação em Propriedade Intelectual e Transferência de Tecnologia para a Inovação",ethicsCommittee:{name:"Comitê de Ética em Pesquisa em Seres Humanos - UFMS",contact:"cepconep.propp@ufms.br | (67) 3345-7187",address:"Av. Costa e Silva, s/n, Bairro Universitário, CEP 79070-900, Campo Grande/MS"},dpo:"Silvia Aratani Marinho - ouvidoria@ifms.edu.br - (67) 3378-9625"},m=[{id:"1",title:"Objetivo da Pesquisa",paragraphs:["Este estudo avalia clareza, relevância, usabilidade e potencial de uso do SRL Canvas (Startup Readiness Level Canvas), ferramenta visual para diagnóstico de maturidade de startups.","As percepções coletadas serão usadas para aprimorar e validar a ferramenta, contribuindo para o ecossistema de inovação e para a literatura acadêmica em empreendedorismo e inovação."]},{id:"2",title:"Justificativa da Pesquisa",paragraphs:["O ecossistema de startups é dinâmico, complexo e possui altas taxas de mortalidade.","A avaliação de maturidade é crucial para empreendedores, investidores e aceleradoras, porém muitas abordagens focam dimensões isoladas.","O SRL Canvas busca fornecer avaliação holística e integrada. Sua participação é essencial para validar a efetividade prática da ferramenta."]},{id:"3",title:"Procedimentos da Pesquisa",paragraphs:["A participação envolve preenchimento de questionário online (10 a 12 minutos).","Opcionalmente, pode haver convite para entrevista semiestruturada de aprofundamento (20 a 30 minutos)."]},{id:"4",title:"Riscos e Desconfortos",paragraphs:["Os riscos são mínimos, restritos a eventual desconforto pelo tempo dedicado ao questionário ou entrevista.","Você pode pular perguntas e encerrar a participação a qualquer momento, sem justificativa e sem prejuízo."]},{id:"5",title:"Benefícios",paragraphs:["Sua participação contribui para o avanço do conhecimento em empreendedorismo e inovação e para o aprimoramento do SRL Canvas.","Se desejar, você poderá receber a versão final do SRL Canvas e/ou relatório-síntese dos resultados da pesquisa."]},{id:"6",title:"Confidencialidade e Anonimato",paragraphs:["As informações coletadas serão tratadas com confidencialidade e usadas exclusivamente para fins acadêmicos.","As respostas serão analisadas de forma agregada, com preservação da identidade, salvo autorização expressa para contato de retorno.","Os dados serão armazenados com acesso restrito ao pesquisador responsável e orientador por até 6 anos no IFMS e eliminados com segurança após esse prazo, em conformidade com a LGPD (Lei 13.709/2018).","Encarregada/DPO do IFMS: Silvia Aratani Marinho - ouvidoria@ifms.edu.br - (67) 3378-9625."]},{id:"7",title:"Direito de Recusa e Retirada",paragraphs:["A participação é voluntária e sem pagamento/compensação financeira.","Você pode recusar participar ou retirar consentimento a qualquer momento, sem necessidade de justificativa e sem prejuízo."]},{id:"8",title:"Contato do CEP",paragraphs:["Projeto submetido ao Comitê de Ética em Pesquisa em Seres Humanos da UFMS (CEP/UFMS), vinculado à Plataforma Brasil.","Contato CEP/UFMS: cepconep.propp@ufms.br | (67) 3345-7187.","Endereço: Av. Costa e Silva, s/n, Bairro Universitário, CEP 79070-900, Campo Grande/MS."]},{id:"9",title:"Declaração de Consentimento",paragraphs:["Declaro que fui informado(a) sobre objetivos, procedimentos, riscos, benefícios e confidencialidade da pesquisa 'Avaliação do SRL Canvas - Diagnóstico de Maturidade de Startups'.","Compreendi as informações apresentadas e tive oportunidade de esclarecer dúvidas.","Consinto de forma livre e espontânea em participar da pesquisa.","CAAE: (a ser preenchido após aprovação do Comitê de Ética)."]}],i="srl-research-consent-v1";function n(){const e=window.localStorage.getItem(i);if(!e)return null;try{return JSON.parse(e)}catch{return null}}function d(e){window.localStorage.setItem(i,JSON.stringify(e))}async function v(e){if(!r||!e){const o=n();return!o||o.revokedAt?{accepted:!1,acceptedAt:null,storage:"none",consentId:null}:{accepted:!0,acceptedAt:o.acceptedAt,storage:"local",consentId:"local"}}const a=await t("/research/consent");return!a.accepted||!a.consentId?{accepted:!1,acceptedAt:null,storage:"none",consentId:null}:{accepted:!0,acceptedAt:a.acceptedAt,storage:"remote",consentId:a.consentId}}function p(){const e=new Date().toISOString();return d({consentVersion:s,acceptedAt:e,revokedAt:null}),{id:e,storage:"local"}}async function f(e){return!r||!e.userId?p():{id:(await t("/research/consent",{method:"POST",body:{consentVersion:s,surveyVersion:c.activeVersion,metadata:{next_path:e.nextPath,accepted_at_client:new Date().toISOString(),source_route:"/survey/consent",user_agent:typeof navigator<"u"?navigator.userAgent:"unknown"}}})).id,storage:"remote"}}async function S(e){if(!r||!e){const a=n();if(!a)return;d({...a,revokedAt:new Date().toISOString()});return}await t("/research/consent/revoke",{method:"POST"})}export{s as R,l as a,m as b,f as c,v as g,S as r};
